Object.assign(SPOKEN, { more: 1 });

// Варианты ответа в случайном порядке, верный — не первым.
function b16Shuffle(list) {
  const a = list.slice();
  for (let i = a.length - 1; i > 0; i -= 1) { const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
  if (a[0] && a[0].right && a.length > 1) a.push(a.shift());
  return a;
}

// Показ урока 1 (useKzDemo) + шаг «нажми сам» (заказчик, v2: на экранах 3 и 6 ученик
// нажимает бирку, голову, бумажку): { tap: 'ключ', el: () => вещь, act }. Пока шаг ждёт,
// вещь мягко пульсирует; экран зовёт demo.tap('ключ') по нажатию.
function useB16Demo({ steps, run: run0, spoken, sayNow, say }) {
  const runRef = useRef(run0);
  const run = runRef.current;
  const [idx, setIdx] = useState(-1);
  const [wait, setWait] = useState(null);
  const ran = useRef(-1);
  const tm = useRef([]);
  const audio = useAudio();
  const pausedRef = useRef(false);
  pausedRef.current = !!(audio && audio.paused);
  useEffect(() => () => tm.current.forEach(clearTimeout), []);
  const later = (ms, f) => {
    const go = () => { if (pausedRef.current) { tm.current.push(setTimeout(go, 300)); return; } f(); };
    tm.current.push(setTimeout(go, ms));
  };
  const next = (i) => setIdx((v) => (v === i ? i + 1 : v));
  const lookAt = (el, i, act) => {
    const done = () => { if (act) act(); next(i); };
    if (!el || !el.classList || reduceMotion()) { done(); return; }
    el.classList.add('kz-demo-on');
    later(560, done);
    later(900, () => el.classList.remove('kz-demo-on'));
  };
  useEffect(() => {
    if (!run) return;
    if (idx === -1) { if (spoken) setIdx(0); return; }
    const st = steps[idx];
    if (!st) return;
    if (ran.current !== idx) {
      if (st.tap && !spoken) return;   // просьба нажать — когда Коди договорил
      ran.current = idx;
      const i = idx;
      if (st.say) { sayNow(st.say[0].text, st.say[0].pose); st.say.slice(1).forEach((l) => say(l.text, l.pose)); return; }
      if (st.tap) { setWait({ key: st.tap, i }); return; }
      if (st.look) { later(200, () => lookAt(st.look(), i, st.act)); return; }
      if (st.wait) { if (st.act) st.act(); later(st.wait, () => next(i)); return; }
      if (st.act) st.act();
      next(i);
      return;
    }
    if (st.say && spoken) next(idx);
  }, [idx, spoken, run]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!wait) return undefined;
    const st = steps[wait.i];
    const el = st && st.el ? st.el() : null;
    if (el && el.classList) el.classList.add('b16-tapme');
    return () => { if (el && el.classList) el.classList.remove('b16-tapme'); };
  }, [wait]); // eslint-disable-line react-hooks/exhaustive-deps
  const tap = (key) => {
    if (!wait || wait.key !== key) return false;
    const st = steps[wait.i];
    const i = wait.i;
    setWait(null);
    if (st.act) st.act();
    next(i);
    return true;
  };
  return { idx, done: !run || idx >= steps.length, step: Math.max(0, Math.min(idx, steps.length)), waiting: wait ? wait.key : null, tap };
}

// Английские слова в узбекской и русской речи — по-английски (заказчик, 28.10.2026:
// «слово tag и все теги читались на английском»). Сервис понимает пометки языка в
// квадратных скобках (как [O'zbekcha tallaffuz] в начале реплики и теги эмоций):
// перед английскими словами ставим [English pronunciation], сразу после — пометку
// языка урока. Узбекское окончание («tag-i») идёт уже после неё.
const B16_BACK = { uz: "[O'zbekcha tallaffuz]", ru: '[Русское произношение]' };
const B16_EN = '(?:tag|HTML|html|head|title|body|doctype|DOCTYPE|CSS|style|transition|ease-in-out|ease-in|ease-out|linear|ease|all|ms|hover|transform|scale|rotate|translate|cursor|pointer|deg|button|position|positon|relative|absolute|fixed|static|top|right|bottom|left|justify-content|align-items|flex-wrap|space-between|flex-start|flex-end|stretch|center|wrap|gap|flex-direction|row-reverse|column-reverse|row|column|flex|nav|inline-block|display|inline|block|none|div|span|Flexbox|border-radius|box-shadow|border-top|border-right|border-bottom|border-left|gray|box-sizing|border-box|content-box|Box Model|margin|padding|border|solid|dashed|dotted|width|height|font-size|px|img|background-image|background-repeat|background-size|no-repeat|repeat|cover|url|background-color|background color|color|class|id|hex|rgb|hsl|orangered|orange|tomato|green|blue|red|purple|lavender|yellow|gold|white|skyblue|navy|lightyellow|darkgreen|selector|property|value|H (?:one|two|three|four|five|six))';
const B16_EN_RE = new RegExp("(^|[^A-Za-z'‘’ʻʼ-])(" + B16_EN + '(?:\\s+' + B16_EN + ')*)(-[A-Za-z]+)?(?![A-Za-z])', 'g');
function b16EnWords(s, lang) {
  const back = B16_BACK[lang];
  if (!back) return s;
  return String(s).replace(B16_EN_RE, (all, pre, words, suf) => pre + '[English pronunciation] ' + words + ' ' + back + (suf || ''));
}
// Голос браузера (когда сервиса озвучки нет) пометки в скобках не понимает и прочёл
// бы их вслух — для него они убираются.
if (typeof window !== 'undefined' && typeof window.SpeechSynthesisUtterance === 'function' && !window.__b16Utt) {
  const BaseUtt = window.SpeechSynthesisUtterance;
  window.__b16Utt = true;
  window.SpeechSynthesisUtterance = function B16Utterance(t) {
    return new BaseUtt(String(t == null ? '' : t).replace(/\[[^\]]*\]/g, ' ').replace(/\s+/g, ' ').replace(/\s+([.,!?;:-])/g, '$1').trim());
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// ОБЛИК «РЕДАКТОР» (тестовый урок 28, 02.11.2026). Заказчик: «попробуй урок в стиле, который
// предложил: герой экрана — код и его результат; код как в настоящем редакторе; оболочка
// игровая, рабочая область строгая; не по-детски; структура урока не меняется».
// Экраны, механики и тексты — урока 1 курса (tools/problemitas17/build.mjs --gen-only);
// здесь — то, что рисует облик:
//   · Sheet — рабочий стол среды разработки: светлое поле в точечной сетке;
//   · PaperMan — свой герой: подросток-верстальщик в плоской линейной графике (худи цвета
//     body, очки, наушники на шее), без «плюшевости»; части и метки — те же, что ждут экраны;
//     голова «открывается» — над ней появляется вкладка браузера с названием (title);
//   · облачко с названием части — как подсказка инспектора DevTools;
//   · kzFly — полёт вкладки-названия прямой дугой, без пружинки.
// Имена p17* оставлены: их ждут экраны урока 1 (правки сборки урока 1).
// ─────────────────────────────────────────────────────────────────────────────
let _p17Scr = 0;   // номер экрана — ставит StageB при отрисовке
// Экран 8 (body), строка задания после показа: коротко, полную фразу Коди говорит голосом.
const P17_S9_DONE = L3('Oynadagi hamma narsa body ichida turadi.', 'Всё, что видно в окне, живёт внутри body.', 'Everything in the window lives inside body.');
const p17Tone = () => ({});

function Sheet({ children, cls }) {
  return (
    <div className={'kz-sheet p17-sheet r28-desk' + (cls ? ' ' + cls : '')}>
      <div className="kz-sheet-body">{children}</div>
    </div>
  );
}

// ── ГЕРОЙ. Поле 200 × 290 (y от 120, земля y = 400) — как у героини урока 1, поэтому раскладка
// экранов и полёты на экране 1 сходятся. Плоская заливка, ровный тёмный контур 2 px.
const P17_W = 200, P17_Y0 = 120, P17_H = 290;
const p17Box = (x0, y0, x1, y1) => ({
  x0, y0, x: (x0 / P17_W) * 100, y: ((y0 - P17_Y0) / P17_H) * 100, w: ((x1 - x0) / P17_W) * 100, h: ((y1 - y0) / P17_H) * 100,
  vb: x0 + ' ' + y0 + ' ' + (x1 - x0) + ' ' + (y1 - y0)
});
const P17B = {
  legL: p17Box(50, 296, 102, 402), legR: p17Box(98, 296, 152, 402),
  armL: p17Box(46, 244, 90, 334), armR: p17Box(110, 244, 154, 334),
  body: p17Box(62, 232, 138, 318), title: p17Box(36, 84, 164, 180), head: p17Box(56, 140, 144, 252)
};
const P17Art = ({ b, children }) => (
  <svg className="p17-art" viewBox={b.vb} preserveAspectRatio="none" aria-hidden="true">{children}</svg>
);

const R28 = { ink: '#1E293B', sw: 2, skin: '#F1C29E', skinD: '#DFA47D', hair: '#1F2430', hood: '#14A391', hoodD: '#0E8473',
  jeans: '#344157', jeansD: '#28334A', html: '#E44D26' };
const rInk = (w = R28.sw) => ({ stroke: R28.ink, strokeWidth: w, strokeLinejoin: 'round', strokeLinecap: 'round' });
// Конечность — толстая линия с контуром: сначала тёмная, сверху цветная.
function RLimb({ d, w, c }) {
  return (
    <g fill="none" strokeLinecap="round" strokeLinejoin="round">
      <path d={d} stroke={R28.ink} strokeWidth={w + R28.sw * 2} />
      <path d={d} stroke={c} strokeWidth={w} />
    </g>
  );
}

// Вкладка браузера с названием страницы — так title и выглядит в браузере.
function R28Tab({ x, y, w, h, text, fs }) {
  const t = String(text || '');
  const tw = w - h * 1.05;
  return (
    <g className="r28-tabchip">
      <rect x={x} y={y} width={w} height={h} rx={h * 0.3} fill="#FFFFFF" {...rInk(1.6)} />
      <circle cx={x + h * 0.48} cy={y + h / 2} r={h * 0.17} fill={R28.html} />
      <text x={x + h * 0.82} y={y + h * 0.66} fontFamily="system-ui, -apple-system, 'Segoe UI', sans-serif" fontSize={fs} fontWeight="700" fill={R28.ink}
        textLength={t.length * fs * 0.56 > tw ? tw : undefined} lengthAdjust="spacingAndGlyphs">{t}</text>
    </g>
  );
}

