    if (!layer) return;
    const b1 = r28Clone(live, layer), b2 = r28Clone(live, layer);
    [0, 1].forEach((f) => setTimeout(() => { r28Band(b1, 22, 7 - f * 3); r28Band(b2, 14, 6 - f * 3); }, f * 45));
